class Solution:
    def intersectionSizeTwo(self, intervals):
        pts = sorted({x for s, e in intervals for x in (s, e)})
        n = len(pts)
        for k in range(2, n + 1):
            import itertools
            for comb in itertools.combinations(pts, k):
                cs = set(comb)
                if all(sum(1 for p in cs if s <= p <= e) >= 2 for s, e in intervals):
                    return k
        return n

