class Solution {
    public int intersectionSizeTwo(int[][] intervals) {
        TreeSet<Integer> pool = new TreeSet<>();
        for (int[] v : intervals) { pool.add(v[0]); pool.add(v[1]); }
        List<Integer> pts = new ArrayList<>(pool);
        int n = pts.size();
        for (int k = 2; k <= n; k++) {
            for (long m = (1L << k) - 1; m < (1L << n); ) {
                boolean ok = true;
                for (int[] v : intervals) {
                    int c = 0;
                    for (int i = 0; i < n && c < 2; i++)
                        if ((m >> i & 1) == 1 && pts.get(i) >= v[0] && pts.get(i) <= v[1]) c++;
                    if (c < 2) { ok = false; break; }
                }
                if (ok) return k;
                long u = m & -m, r = m + u;
                m = (((r ^ m) / u) >> 2) | r;
            }
        }
        return n;
    }
}

