var intersectionSizeTwo = function(intervals) {
    const pool = [...new Set(intervals.flat())].sort((a, b) => a - b);
    const n = pool.length;
    const check = (mask) => intervals.every(([s, e]) => {
        let c = 0;
        for (let i = 0; i < n && c < 2; i++)
            if (mask >> i & 1 && pool[i] >= s && pool[i] <= e) c++;
        return c >= 2;
    });
    for (let k = 2; k <= n; k++) {
        let mask = (1 << k) - 1;
        while (mask < (1 << n)) {
            if (check(mask)) return k;
            const u = mask & -mask, r = mask + u;
            mask = (((r ^ mask) / u) >> 2) | r;
        }
    }
    return n;
};

